use vstd::prelude::*;

verus! {
    // A predicate saying that a sequence s of length n
    // uses only 'a' or 'b', and for every i ≤ n-3, s[i] != s[i+2].
    spec fn valid_seq(s: Seq<char>, n: nat) -> bool {
        s.len() == n
        && forall |i: nat| i + 2 < n ==> s[i] != s[i+2]
        && forall |i: nat| i < n ==> s[i] == 'a' || s[i] == 'b'
    }

    fn solve(n: i8) -> (result: Vec<char>)
        requires
            n >= 1,
        ensures
            valid_seq(result@, (n as nat))
    {
        let mut res: Vec<char> = Vec::new();
        let mut i: i8 = 0;
        while i < n
            invariant 0 <= i && i <= n,
            invariant res.len() == (i as usize),
            invariant forall |j: nat| j + 2 < (i as nat) ==> res@[j] != res@[j+2],
            invariant forall |j: nat| j < (i as nat) ==> res@[j] == 'a' || res@[j] == 'b',
            decreases (n - i) as nat,
        {
            // cycle through 0,1,2,3
            let k = (i % 4) as u8;
            // for k=0,1 => 'a'; for k=2,3 => 'b'
            let c = if k < 2 { 'a' } else { 'b' };

            // when i >= 2 we must check that the new character
            // still satisfies res[i-2] != res[i]
            if i >= 2 {
                let prev_idx = (i - 2) as usize;
                assert(res@[prev_idx] != c) by {
                    // pattern is [a,a,b,b]: P[0]=a,P[1]=a,P[2]=b,P[3]=b],
                    // so P[k] != P[(k+2)%4].  A short case‐analysis closes it.
                    match k {
                        0 => { } // P[0]=a, P[2]=b
                        1 => { } // P[1]=a, P[3]=b
                        2 => { } // P[2]=b, P[0]=a
                        3 => { } // P[3]=b, P[1]=a
                        _ => unreachable!()
                    }
                }
            }

            res.push(c);
            i = i + 1;
        }

        res
    }
}

fn main() {
    // testing by hand:
    let v = solve(10);
    // v should be ["a","a","b","b","a","a","b","b","a","a"]
    println!("{:?}", v);
}